We're replacing TanStack Query with Data Client. `DiscussionResource` (resource() with `path: '/discussions/:id'`, schema `Discussion` Entity; `getList` takes `{ page }` and the list is a table split into numbered pages) is already defined in src/api/discussion.ts. Convert these two hooks and their callers in src/features/discussions/ so they no longer use TanStack Query:

```ts
export const useUpdateDiscussion = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: { title: string; body: string } }) =>
      api.patch(`/discussions/${id}`, data),
    onSuccess: (data) => {
      queryClient.refetchQueries({ queryKey: ['discussions', data.id] });
    },
  });
};

export const useCreateDiscussion = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (data: { title: string; body: string }) => api.post('/discussions', data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['discussions'] });
    },
  });
};
```

Callers use `mutation.mutate(values)`, `mutation.isPending` for the submit button, and `mutation.isSuccess` to close the form drawer.

Replace this TanStack Query infinite list with Data Client. The API is `GET /comments?discussionId=..&page=..` returning `{ data: Comment[], meta: { page: number, totalPages: number } }`, and `POST /comments?discussionId=..` with `{ body }` returns the new Comment. Comment has `id`, `body`, `discussionId`.

```tsx
export const getInfiniteCommentsQueryOptions = (discussionId: string) =>
  infiniteQueryOptions({
    queryKey: ['comments', discussionId],
    queryFn: ({ pageParam = 1 }) => getComments({ discussionId, page: pageParam as number }),
    getNextPageParam: (lastPage) =>
      lastPage.meta.page === lastPage.meta.totalPages ? undefined : lastPage.meta.page + 1,
    initialPageParam: 1,
  });

export function CommentsList({ discussionId }: { discussionId: string }) {
  const commentsQuery = useInfiniteQuery(getInfiniteCommentsQueryOptions(discussionId));
  if (commentsQuery.isLoading) return <Spinner />;
  const comments = commentsQuery.data?.pages.flatMap((page) => page.data);
  return (
    <>
      <ul>{comments?.map((c) => <li key={c.id}>{c.body}</li>)}</ul>
      {commentsQuery.hasNextPage && (
        <button onClick={() => commentsQuery.fetchNextPage()}>
          {commentsQuery.isFetchingNextPage ? 'Loading' : 'Load more'}
        </button>
      )}
    </>
  );
}

// after creating a comment:
queryClient.invalidateQueries({ queryKey: getInfiniteCommentsQueryOptions(discussionId).queryKey });
```

